// An external-link icon decorates external destinations without replacing descriptive text.
(()=>{function decorate(){for(const link of document.querySelectorAll('a[href^="https://"],a[href^="http://"]')){if(link.origin===location.origin||link.dataset.externalIcon)continue;link.dataset.externalIcon='true';for(const node of link.childNodes)if(node.nodeType===3)node.textContent=node.textContent.replace(/↗/g,'').trimEnd();const icon=document.createElementNS('http://www.w3.org/2000/svg','svg');icon.setAttribute('viewBox','0 0 24 24');icon.setAttribute('class','external-paperclip');icon.setAttribute('aria-hidden','true');icon.innerHTML='<path d="M14 3h7v7M21 3l-11 11M10 5H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-5" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/>';link.append(icon);const accessible=document.createElement('span');accessible.className='visually-hidden';accessible.textContent=' (external link)';link.append(accessible);if(link.hasAttribute('aria-label'))link.setAttribute('aria-label',link.getAttribute('aria-label')+' (external link)');}}
 let pending=false;new MutationObserver(()=>{if(!pending){pending=true;requestAnimationFrame(()=>{pending=false;decorate();});}}).observe(document.body,{childList:true,subtree:true});decorate();})();
